INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('life-changing', 'Меняют жизнь', 'Книги, которые меняют жизнь', 'Книги, разделившие жизнь на до и после: клубчане рассказывают, что вынесли из них и как это изменило их взгляд на себя и мир.', '#e9e5f4', 'recommendations', 'post-2389', 'https://vas3k.club/post/2389/', 'Книги, которые разделили мою жизнь на до и после', '2026-11-11T23:21:08.282Z', 0, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('unusual', 'Необычные книги', 'Необычные книги', 'Ни на что не похожий читательский опыт: романы-загадки, переписка на полях и книги, которые играют с самой формой чтения.', '#f4e6da', 'recommendations', 'post-6558', 'https://vas3k.club/post/6558/', 'Необычные книги', '2026-11-11T23:21:08.282Z', 1, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('science', 'Научпоп', 'Научпоп, который увлекает', 'Ответы на вопрос о научпопе, который «вот прямо очень зашёл»: книги о человеке, природе и устройстве мира, увлёкшие клубчан.', '#e0ece7', 'recommendations', 'question-4784', 'https://vas3k.club/question/4784/', 'Посоветуйте научпоп книги которые вам вот прямо очень зашли?', '2026-11-11T23:21:08.282Z', 2, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('childhood', 'Из детства', 'Любимые книги детства', 'Клубчане вспоминают книги своего детства — истории, с которыми росли, которые перечитывали и помнят до сих пор.', '#f4ecd8', 'recommendations', 'question-32013', 'https://vas3k.club/question/32013/', 'Книги вашего детства?', '2026-11-11T23:21:08.282Z', 3, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('best-2025', 'Лучшее — 2025', 'Любимые книги 2025 года', 'Лучшее из прочитанного клубчанами в 2025 году, независимо от даты издания. В исходной теме выбирали тройку любимых книг и обсуждали разочарования и guilty pleasure.', '#e2eaf3', 'recommendations', 'thread-30223', 'https://vas3k.club/thread/30223/', 'Топ книг 2025', '2026-11-11T23:21:08.282Z', 4, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('best-2024', 'Лучшее — 2024', 'Любимые книги 2024 года', 'Лучшее из прочитанного клубчанами в 2024 году, независимо от даты издания. В исходной теме выбирали тройку любимых книг и обсуждали разочарования и guilty pleasure.', '#ece5ed', 'recommendations', 'thread-26660', 'https://vas3k.club/thread/26660/', 'Топ книг 2024', '2026-11-11T23:21:08.282Z', 5, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('best-2023', 'Лучшее — 2023', 'Любимые книги 2023 года', 'Лучшее из прочитанного клубчанами в 2023 году, независимо от даты издания. В исходной теме выбирали тройку любимых книг и обсуждали разочарования.', '#e5ebdd', 'recommendations', 'thread-22046', 'https://vas3k.club/thread/22046/', 'Топ книг 2023', '2026-11-11T23:21:08.282Z', 6, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('best-2022', 'Лучшее — 2022', 'Любимые книги 2022 года', 'Книжные итоги 2022 года: личные топы, анти-топы и читательские челленджи. Здесь — книги, которые клубчане выделили среди лучших.', '#efe4db', 'recommendations', 'post-17764', 'https://vas3k.club/post/17764/', 'Книжные итоги года и челенджи 2022', '2026-11-11T23:21:08.282Z', 7, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('best-2021', 'Лучшее — 2021', 'Любимые книги 2021 года', 'Личные книжные топы клубчан за 2021 год: что запомнилось больше всего из прочитанного и почему хочется посоветовать это другим.', '#e3e8ea', 'recommendations', 'post-13301', 'https://vas3k.club/post/13301/', 'Ваш топ книг — 2021', '2026-11-11T23:21:08.282Z', 8, CURRENT_TIMESTAMP);
INSERT INTO "book_collections" ("slug", "tile_title", "title", "description", "color", "intent", "source_id", "source_url", "source_title", "source_snapshot_at", "sort_order", "updated_at") VALUES ('not-recommended', 'Не советуют', 'Книги, которые не советуют читать', 'Книги, от чтения которых клубчане предостерегают, и их аргументы: чем популярная рекомендация может навредить. Критикуют книги, а не читателей.', '#f3e2df', 'anti_recommendations', 'thread-23224', 'https://vas3k.club/thread/23224/', 'Какие книги не стоит читать?', '2026-11-11T23:21:08.282Z', 9, CURRENT_TIMESTAMP);
